SELECT  json_build_object('aggregate', json_build_object('count', COUNT(*) ), 'nodes', (SELECT  coalesce(json_agg("_sub_query"."root.f.nodes" ORDER BY "ob_col_1" DESC NULLS FIRST), '[]' )  FROM  (SELECT  "_unnest_table"."root.f.nodes" AS "root.f.nodes", "_unnest_table"."ob_col_1" AS "ob_col_1" FROM UNNEST(array_agg("root.f.nodes" ), array_agg("root.pg.id" )) AS "_unnest_table"("root.f.nodes", "ob_col_1")    ORDER BY "ob_col_1" DESC NULLS FIRST LIMIT 2 ) AS "_sub_query"      ) ) AS "root" FROM  (SELECT  row_to_json((SELECT  "_e"  FROM  (SELECT  "_root.base"."id" AS "id"       ) AS "_e"      ) ) AS "root.f.nodes", "_root.base"."id" AS "root.pg.id" FROM  (SELECT  *  FROM "public"."author"  WHERE ('true')   ORDER BY "id" DESC NULLS FIRST LIMIT 5 ) AS "_root.base"    ORDER BY "root.pg.id" DESC NULLS FIRST  ) AS "_root"      
